namespace BoatsNBeasts.Core;

public static partial class FarLedger
{
    static CampaignArc Drumskin() => CampaignArc.Create("Drumskin Gulf", "Two Beats Apart",
        "At Drumskin Gulf the sea floor answers every footstep a beat late. Vara recognizes the rhythm her brother once knocked through their cabin wall. Oren recognizes the answering knock and asks who has been playing his part.",
        "Two separate palm drums in a case wide enough for both",
        new("Ina Keel  /  shore drummer",
            "Who should hear the silence between the beats?",
            "The two largest islands have drifted within speaking distance. Ina can give Vara the upwind drum to address the families she left, or let Oren carry a small reply drum to the people who waited for him. Neither can speak for the other.",
            "Give Vara the upwind drum",
            "Take Oren to the listening shore",
            "Vara takes the drum alone. Oren sits down among the listeners, with both hands where his sister can see them.",
            "Oren carries the reply drum himself. Vara keeps the gun deck quiet until he has finished, even when he stops in the middle."),
        14,
        [
            Crossing("wake-drum-knuckle", SeaDuty.Sounding, "Knocks Through the Floor",
                "Vara used to keep a lamp lit for Oren by tapping on the wall after curfew. She hears that rhythm again in a gulf full of islands stretched between floating hoops.",
                "Locate the pair of islands sending the cabin rhythm.", "Snarefin",
                "One knock comes from a village of dock children. The other comes from a vacant house whose floorboards remember Oren’s hands.", 8, SeaJob.Sound, SeaJob.Relay, SeaJob.Track),
            Landfall("wake-drum-house", "An Empty House Answers",
                "Oren wants to lift the drumskin from the empty house before anyone asks it what he meant. Ina says the house has earned the right to be heard as a house.", "Resonance Tortoise",
                "A shell trapped under one floorboard has been answering all this time. Oren asks Ina to show him how to listen without tapping back.", 9,
                At(LandingAction.Brace, YardSite.West, "Floor hoop", "Brace the house hoop without stretching its skin"),
                At(LandingAction.Haul, YardSite.East, "Reply shell", "Lift the reply shell into open air"),
                At(LandingAction.Seat, YardSite.Crane, "Listening stand", "Seat the living shell on Ina’s listening stand")),
            Crossing("wake-drum-vara", SeaDuty.Convoy, "Vara Faces the Wind",
                "Vara takes the upwind drum to the families she left during the registry years. She has written five accounts in a notebook and cannot bring herself to read any of them.",
                "Bring Vara’s listening barge to the families on Bell Lip.", "Sternhead Porpoise",
                "Vara closes the notebook. She says she was afraid that staying in touch would bring the registry to their doors. A mother says she would have liked the choice.", 9, SeaJob.Tow, SeaJob.Relieve, SeaJob.Guide),
            Landfall("wake-drum-oren", "What Oren Can Carry",
                "Oren asks the ferry crews to give him their undelivered parcels one at a time. A dozen parcels reach him before the first owner has spoken. His arms begin to shake.", "Parcel Rack Hound",
                "Oren puts the parcels down and asks the first owner to start again. Vara works at the other end of the shed, where he cannot look to her for his answer.", 9,
                At(LandingAction.Haul, YardSite.West, "Parcel trestle", "Haul a dry trestle beside the ferry"),
                At(LandingAction.Seat, YardSite.East, "Owner’s stool", "Seat the owner’s stool opposite Oren"),
                At(LandingAction.Guide, YardSite.Stairs, "First parcel owner", "Walk the first owner to the listening shed")),
            Crossing("wake-drum-paired", SeaDuty.Salvage, "A Case for Two",
                "Ina made two little drums for the children who used to live in the empty house. The case went down with the old parcel ferry. Each drum holds a different note when wet.",
                "Raise both palm drums without stretching their skins.", "Hideback Ray",
                "Vara keeps the larger drum and Oren the smaller. The case opens along its middle. Each can carry their own way of answering.", 9, SeaJob.Track, SeaJob.Salvage, SeaJob.Unload),
            Crossing("wake-drum-space", SeaDuty.Convoy, "A Beat Nobody Plays",
                "A school of young islands is trying to follow the gulf’s procession. Every drum is playing so loudly that the smallest island cannot find a place in the rhythm.",
                "Guide the small island through the gap in the gulf procession.", "Hollow Dolphin",
                "Vara leaves one beat open. Oren waits through it. The little island sounds quite different from either of them, and the procession turns to follow.", 9, SeaJob.Guide, SeaJob.Relay, SeaJob.Relieve)
        ],
        Crossing("wake-drum-reply", SeaDuty.Sounding, "Oren on the Listening Shore",
            "Oren remembers the registry’s warning bells better than the faces he left behind. He asks the children to name their own island sounds before he tries to tell them his story.",
            "Find a quiet anchorage for each family’s account.", "Whisper Conger",
            "One child asks him to repeat the uninteresting part about carrying luggage. Oren tells her how he used to fold the straps, and she shows him a better knot.", 9, SeaJob.Sound, SeaJob.Guide, SeaJob.Relay));

    static IslandStory[] DrumskinIsles() =>
    [
        Isle("Drumskin Gulf",14,"Goatskin Reach","Em, hoop fitter",
            "Em fits hoops to islands whose old skins grow too tight. The island underneath her wedding house has outgrown its hoop overnight. Her wife is out buying supper and cannot find the house.", "An adjustable hoop no larger than a bracelet",
            new PostLetter("A wedding ring on a strip of goatskin",
                "My wife and I each wore the traveling ring for a week until the house settled down. Its inside has picked up two sets of marks. Which hand shall we give it to?",
                "Ina sends them a little stand for the ring beside the front door."),
            Crossing("wake-hoop-supper", SeaDuty.Convoy, "Supper for a Moving House",
                "Em’s wife can hear their wedding kettle from the grocer’s boat. The kettle and the boat seem to be travelling in opposite directions.",
                "Bring the grocer and supper to the wandering kettle.", "Stockpot Dolphin",
                "A whistle comes out of the grocery sack. Both women packed kettles when they moved in and each thought the other had disposed of hers.", 8, SeaJob.Guide, SeaJob.Tow, SeaJob.Relay),
            Landfall("wake-hoop-buckle", "One More Hole",
                "Em can loosen the island hoop by one notch if the wedding house stays level. Her oldest friend is still inside holding a plate of pears.", "Buckle Stoat",
                "The island takes a long breath. The pears stay on the plate. Em asks her friend to leave one under the warmest floorboard.", 9,
                At(LandingAction.Brace, YardSite.West, "House shoe", "Hold the house level at the low corner"),
                At(LandingAction.Haul, YardSite.East, "Hoop tongue", "Draw the tongue to the next hole"),
                At(LandingAction.Seat, YardSite.Fallen, "New buckle", "Set the longer buckle in the loose skin")),
            Crossing("wake-hoop-vow", SeaDuty.Salvage, "A Very Small Circle",
                "Em lost her wedding ring while she was fitting the buckle. Somewhere below is a metal hoop small enough for a finger and dear enough for a whole house.",
                "Recover the ring from the shed hoops on the seabed.", "Bracelet Skate",
                "It fits on the toe of a newly hatched island. The little island objects to giving it back until offered the pear.", 8, SeaJob.Track, SeaJob.Salvage, SeaJob.Bait),
            Landfall("wake-hoop-house", "A Door That Travels",
                "The two kettles call from opposite ends of the house. Em can give the kitchen a moving hinge so either wife can find the door from a passing boat.", "Lintel Grouse",
                "The kettles whistle together at supper. Em sets the little ring beside their travelling door.", 9,
                At(LandingAction.Seat, YardSite.West, "Round hinge", "Fit the round hinge below the kitchen"),
                At(LandingAction.Turn, YardSite.East, "New sill", "Turn the sill to face the grocery boat"),
                At(LandingAction.Guide, YardSite.Stairs, "House guest", "Lead the guest and the pears to supper"))),
        Isle("Drumskin Gulf",14,"Rest Mark","Dov, silence keeper",
            "Dov paints the rests on the gulf’s public scores. A black rest has slipped off the page and lodged under the busiest drum. The ferry steps have been silent all morning.", "A paintbrush with a quiet spot halfway down its handle",
            new PostLetter("A folded square of silence",
                "Open this indoors. It is the quiet between two people trying to say the same difficult thing. We have plenty here for the time being.",
                "Vara keeps the square in the galley until a conversation needs it."),
            Crossing("wake-rest-steps", SeaDuty.Sounding, "The Ferry Cannot Hear Its Feet",
                "At Rest Mark the watch follows the drumming of ferry feet. Dov’s black rest has erased an entire morning service, although the passengers are standing on the steps.",
                "Find the edge of the silence along the ferry route.", "Mute Bill",
                "The mute patch has the shape of a man asleep on a bench. Dov recognizes the night porter who used to ride for free.", 8, SeaJob.Sound, SeaJob.Track, SeaJob.Relay),
            Landfall("wake-rest-bench", "Under the Sleeper",
                "The porter is still asleep inside the rest. Dov has painted over him in every public score for forty years, thinking he was a smudge in the paper.", "Bench Tick",
                "The porter wakes only long enough to thank Dov for the good bench. Nobody asks him to move until his shift begins.", 9,
                At(LandingAction.Haul, YardSite.West, "Bench braces", "Lift the braces from the old bench"),
                At(LandingAction.Cut, YardSite.East, "Paint skin", "Cut the silence round the porter’s coat"),
                At(LandingAction.Brace, YardSite.Fallen, "Seat back", "Hold the seat while Dov frees the rest")),
            Crossing("wake-rest-break", SeaDuty.Blockade, "A Break Each Way",
                "The guild grants one minute’s rest per shift to the boat and none to the ferryman. Dov wants to carry the loose quiet to the oarsmen on the far side.",
                "Pass the overtime booms with the quiet parcel.", "Timecard Pike",
                "Every oar comes out of the water at once. The boats drift together until their passengers start talking.", 9, SeaJob.Cut, SeaJob.Guide, SeaJob.Relieve),
            Landfall("wake-rest-both", "Room on the Bench",
                "Two shifts end at the same hour. The old bench seats one. Dov brings a long blank rest and a tin of paint the color of warm bread.", "Paintpot Fox",
                "Both crews sleep through the first ferry bell. Their passengers agree the crossing can start late once a week.", 9,
                At(LandingAction.Seat, YardSite.East, "Second plank", "Set the long plank across both shifts"),
                At(LandingAction.Turn, YardSite.West, "Watch dial", "Turn the dial to the shared break"),
                At(LandingAction.Guide, YardSite.Stairs, "Night porter", "Walk the porter to the far end of the bench"))),
        Isle("Drumskin Gulf",14,"Heel of Thunder","Sai, boot cobbler",
            "Sai makes quiet boots for people who live on a drum. Her own child wants boots that can be heard from every floating island in the gulf.", "Sai’s tiny thunder heel",
            new PostLetter("One bootlace and a map of the places it has been",
                "I left a loose end on purpose. A child is growing at the other end of this boot and the road will have to grow too.",
                "Lio adds a sailor’s bend that can be untied with one hand."),
            Landfall("wake-heel-last", "The Loud Last",
                "A thunder heel is stuck on the cobbler’s last. Sai has tried asking it politely. Its answer woke three whole islands and the harbor dog.", "Bootlace Adder",
                "The heel squeaks when the child touches it. Sai hears the squeak clearly over all the thunder.", 8,
                At(LandingAction.Brace, YardSite.West, "Cobbler’s last", "Brace the wooden last inside the silent booth"),
                At(LandingAction.Cut, YardSite.East, "Storm stitch", "Cut the loudest stitch at its loose end"),
                At(LandingAction.Haul, YardSite.Fallen, "Thunder heel", "Pull the heel free toward Sai")),
            Crossing("wake-heel-run", SeaDuty.Hunt, "Somewhere a Child Is Running",
                "The child takes a practice run around a floating island. Each footfall sets a second island echoing. Sai is afraid a thunderstorm is going to answer first.",
                "Follow the true heel among its echoes.", "Rolling Drumray",
                "The answering footsteps belong to a child on the farthest island. The two runners have been playing tag across open water.", 9, SeaJob.Track, SeaJob.Bait, SeaJob.Sound),
            Crossing("wake-heel-pair", SeaDuty.Convoy, "Send the Other Boot",
                "The second runner has only quiet boots. Sai offers to make the pair one loud boot each. The children disagree about who gets the left.",
                "Deliver the unfinished boot to the far runner’s island.", "Leftfoot Tunny",
                "The children exchange boots and both run in circles. Sai adds a little brass heel counter for the straight stretches.", 9, SeaJob.Tow, SeaJob.Relieve, SeaJob.Guide),
            Landfall("wake-heel-road", "A Road Drawn in Noise",
                "The pair need a place to run together where footfalls will leave the nursery asleep. The old public drum has a crack Sai can use as a sound drain.", "Crackle Drake",
                "The children run along the quiet arc, reach the end and stamp once. Two islands answer from the same place.", 9,
                At(LandingAction.Haul, YardSite.West, "Sound drain", "Hoist the old sound drain into its crack"),
                At(LandingAction.Seat, YardSite.East, "Heel counter", "Seat the brass counter at the bend"),
                At(LandingAction.Turn, YardSite.Crane, "Practice gate", "Open the quiet running road"))),
        Isle("Drumskin Gulf",14,"Old Hide Observatory","Uri, night reader",
            "The observatory records stars by their vibrations on an island skin. Every chart now shows a small bright object beneath the floor. Uri is the only observer willing to look down.", "A star punch in a soft leather case",
            new PostLetter("A chart drawn on both sides of a drum circle",
                "There is a sky above the skin and another underneath. I have drawn the same star twice. Please ask it which side it would like to be on.",
                "Nell pricks a single hole through both charts so the star can look at itself."),
            Crossing("wake-hide-below", SeaDuty.Sounding, "A Star Under the Stool",
                "Uri has measured the bottom star every night for a month. It rises when someone sits in the oldest observing chair and sets when they go home.",
                "Plot the vibration under the observatory.", "Stoolfoot Skate",
                "The star is a luminous egg rolling in the cradle of the old island. The sound of a seated observer calms it.", 9, SeaJob.Sound, SeaJob.Track, SeaJob.Relay),
            Landfall("wake-hide-stool", "Take the Night Watch",
                "Uri wants to shift the observing chair without waking the luminous egg. He has been sitting still for six hours and would like someone to bring him soup.", "Meridian Wren",
                "The chair rolls to the new cradle. Uri eats his soup. The egg turns once and settles beneath his feet.", 9,
                At(LandingAction.Brace, YardSite.West, "Chair runner", "Brace the chair while the cradle shifts"),
                At(LandingAction.Seat, YardSite.East, "Soft caster", "Fit the soft caster under Uri’s stool"),
                At(LandingAction.Guide, YardSite.Stairs, "Night reader", "Help Uri wheel his chair to the new watch")),
            Crossing("wake-hide-punch", SeaDuty.Salvage, "One Hole of Light",
                "The old observatory’s star punch can mark the egg’s true position without touching it. The punch went down in a leather case when the first dome rolled over.",
                "Raise the star punch from the drowned dome.", "Leatherback Pointer",
                "The punch is still sharp. Its first hole lets a little saltwater out and one clean shaft of starlight in.", 9, SeaJob.Track, SeaJob.Salvage, SeaJob.Unload),
            Landfall("wake-hide-open", "The Dome Opens Down",
                "The luminous egg is ready to hatch. Uri has a dome that opens upward and a nursery that opens toward the bottom of the sea.", "Domeback Turtle",
                "A star-bright island swims down from the drum and turns slowly in the dark. Uri closes his notebook before it disappears.", 9,
                At(LandingAction.Cut, YardSite.West, "Dome straps", "Cut the old upper straps"),
                At(LandingAction.Turn, YardSite.East, "Lower iris", "Open the lower iris toward deep water"),
                At(LandingAction.Brace, YardSite.Crane, "Nursery hammock", "Hold the hammock while the hatchling leaves")))
    ];
}
